p.deleted_at IS NULL AND p.hidden_at IS NULL AND p.status = 'PUBLISHED' AND p.visibility = 'PUBLIC'
AND b.slug = #{f.boardSlug}
AND p.author_id = #{f.authorId}
AND (LOWER(p.title) LIKE LOWER(#{f.pattern}) ESCAPE '!' OR LOWER(p.content) LIKE LOWER(#{f.pattern}) ESCAPE '!')
AND EXISTS (SELECT 1 FROM post_tag pt JOIN tag t ON t.id = pt.tag_id WHERE pt.post_id = p.id AND t.name = #{f.tag})
AND p.created_at >= #{f.from}
AND p.created_at < #{f.to}
